const fs = require('fs');
const path = require('path');

const candidates = [
  'c:/Users/chava/OneDrive/Desktop/SKH/server/data/kopargaon_smart_city_dataset.csv',
  'c:/Users/chava/OneDrive/Desktop/SKH/kopargaon_smart_city_dataset.csv',
  path.join(process.cwd(), 'server/data/kopargaon_smart_city_dataset.csv'),
  path.join(process.cwd(), 'kopargaon_smart_city_dataset.csv')
];

let content = '';
for (const p of candidates) {
  if (fs.existsSync(p)) {
    content = fs.readFileSync(p, 'utf8');
    break;
  }
}

if (!content) {
  return [{ json: { error: 'CSV file not found' } }];
}

const lines = content.trim().split('\n');
const results = [];

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const fields = [];
  let inQuotes = false;
  let cur = '';
  for (let j = 0; j < line.length; j++) {
    const char = line[j];
    if (char === '"') {
      if (inQuotes && line[j + 1] === '"') { cur += '"'; j++; }
      else { inQuotes = !inQuotes; }
    } else if (char === ',' && !inQuotes) {
      fields.push(cur.trim());
      cur = '';
    } else {
      cur += char;
    }
  }
  fields.push(cur.trim());
  if (fields.length >= 3) {
    const category = fields[0];
    const rawQuery = fields[1];
    const answer = fields[2];
    const cleanQuery = rawQuery.replace(/^\d+\.\s*/, '').trim();
    results.push({
      json: {
        category,
        query: cleanQuery,
        rawQuery,
        answer,
        pageContent: `Category: ${category}\nQuestion: ${cleanQuery}\nAnswer: ${answer}`
      }
    });
  }
}

return results;

