const axios = require('axios');
const toolName = $parameter.toolName;
const args = $parameter.arguments || {};
const primaryUrl = process.env.MCP_SERVER_URL || 'http://localhost:7000';
try {
  const response = await axios.post(`${primaryUrl}/call`, {
    name: toolName,
    arguments: args
  }, { timeout: 8000 });
  return JSON.stringify(response.data.result || response.data);
} catch (e) {
  return `Error calling MCP tool ${toolName}: ${e.message}`;
}

